			if field["name"] not in last_applied_manifest:
				last_applied_manifest[field["name"]] = []
			update_last_applied_manifest_list_from_resp(
				last_applied_manifest[field["name"]],
				field["observer_schema"],
				response[i],
			)
		else:
			if field["name"] not in last_applied_manifest:
